const int MAXN = 10001;
struct Edge { int v, p; int c, w; };
vector<Edge> graph[MAXN];
int visited[MAXN], current[MAXN], nodeCount;
int dist[MAXN], potential[MAXN];

int addVertices(int count) {
    while (count--) graph[nodeCount++].clear();
    return nodeCount - 1;
}

void addEdge(int u, int v, int capacity, int weight) {
    graph[u].push_back({ v, (int)graph[v].size(), capacity, weight });
    graph[v].push_back({ u, (int)graph[u].size() - 1, 0, -weight });
}

bool dijkstra(int start, int end) {
    fill_n(dist, nodeCount, INF);
    fill_n(visited, nodeCount, 0);
    typedef pair<int, int> pli;
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    pq.push({ dist[start] = 0, start });
    while (!pq.empty()) {
        int u, du; tie(du, u) = pq.top(); pq.pop();
        if (visited[u]) continue; visited[u] = 1;
        for (auto &edge : graph[u]) {
            int v = edge.v; int dv = du + potential[u] + edge.w - potential[v];
            if (!edge.c || visited[v] || dist[v] <= dv) continue;
            pq.push({ dist[v] = dv, v });
        }
    }
    return visited[end];
}

bool bfsLevelGraph(int start, int end) {
    fill_n(visited, nodeCount, 0);
    queue<int> q; q.push(start); visited[start] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto &e : graph[u]) {
            int v = e.v;
            if (visited[v] || !e.c) continue;
            if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1; q.push(v);
        }
    }
    return visited[end] != 0;
}

int dfsFlow(int u, int t, int flow) {
    if (u == t) return flow;
    int totalFlow = 0;
    for (int &i = current[u]; i < (int)graph[u].size(); ++i) {
        auto &e = graph[u][i]; int v = e.v;
        if (!e.c || visited[v] != visited[u] + 1) continue;
        if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
        int pushed = dfsFlow(v, t, min(e.c, flow));
        totalFlow += pushed; flow -= pushed; e.c -= pushed; graph[v][e.p].c += pushed;
