import java.util.*;
import java.io.*;

public class Main {
    static final int INF = Integer.MAX_VALUE;

    static class Edge {
        int v, p, c, w;
        Edge(int v, int p, int c, int w) {
            this.v = v;
            this.p = p;
            this.c = c;
            this.w = w;
        }
    }

    static class Flow {
        static final int MAXN = 10001;
        List<Edge>[] graph = new ArrayList[MAXN];
        int[] visited = new int[MAXN];
        int[] current = new int[MAXN];
        int nodeCount;
        int[] dist = new int[MAXN];
        int[] potential = new int[MAXN];

        Flow() {
            for (int i = 0; i < MAXN; i++) {
                graph[i] = new ArrayList<>();
            }
        }

        int addVertices(int count) {
            int startNodeCount = nodeCount;
            for (int i = 0; i < count; i++) {
                graph[nodeCount++].clear();
            }
            return startNodeCount;
        }

        void addEdge(int u, int v, int capacity, int weight) {
            graph[u].add(new Edge(v, graph[v].size(), capacity, weight));
            graph[v].add(new Edge(u, graph[u].size() - 1, 0, -weight));
        }

        boolean dijkstra(int start, int end) {
            Arrays.fill(dist, 0, nodeCount, INF);
            Arrays.fill(visited, 0, nodeCount, 0);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[start] = 0;
            pq.offer(new int[]{0, start});
            while (!pq.isEmpty()) {
                int[] top = pq.poll();
                int du = top[0], u = top[1];
                if (visited[u] != 0) continue;
                visited[u] = 1;
                for (Edge e : graph[u]) {
                    int v = e.v;
                    int dv = du + potential[u] + e.w - potential[v];
                    if (e.c == 0 || visited[v] != 0 || dist[v] <= dv) continue;
                    dist[v] = dv;
                    pq.offer(new int[]{dist[v], v});
                }
            }
            return visited[end] != 0;
        }

        boolean bfsLevelGraph(int start, int end) {
            Arrays.fill(visited, 0, nodeCount, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(start);
            visited[start] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : graph[u]) {
                    int v = e.v;
                    if (visited[v] != 0 || e.c == 0) continue;
                    if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
                    visited[v] = visited[u] + 1;
                    q.offer(v);
                }
            }
            return visited[end] != 0;
        }

        int dfsFlow(int u, int t, int flow) {
            if (u == t) return flow;
            int totalFlow = 0;
            for (int i = current[u]; i < graph[u].size(); i++) {
                Edge e = graph[u].get(i);
                int v = e.v;
                if (e.c == 0 || visited[v] != visited[u] + 1) continue;
                if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
                int pushed = dfsFlow(v, t, Math.min(e.c, flow));
                if (pushed > 0) {
                    e.c -= pushed;
                    graph[v].get(e.p).c += pushed;
                    totalFlow += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
                current[u]++;
            }
            return totalFlow;
        }

        int[] minCostMaxFlow(int s, int t, int maxFlow) {
            int flowSum = 0, costSum = 0;
            Arrays.fill(potential, 0, nodeCount, 0);
            while (dijkstra(s, t)) {
                int flow = 0;
                while (bfsLevelGraph(s, t)) {
                    Arrays.fill(current, 0, nodeCount, 0);
                    int pushedFlow = dfsFlow(s, t, maxFlow);
                    maxFlow -= pushedFlow;
                    flow += pushedFlow;
                    if (pushedFlow == 0) break;
                }
                flowSum += flow;
                costSum += (dist[t] + potential[t]) * flow;
                for (int i = 0; i < nodeCount; i++) {
                    potential[i] += dist[i];
                }
                if (maxFlow == 0) break;
            }
            return new int[]{flowSum, costSum};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int totalVertices = Math.max(n, k) * 2;
        Flow flow = new Flow();
        int source = flow.addVertices(1);
        int sink = flow.addVertices(1);
        flow.nodeCount = 0; // reset node count after adding source and sink
        flow.nodeCount = Math.max(flow.nodeCount, source + 1);
        flow.nodeCount = Math.max(flow.nodeCount, sink + 1);
        flow.nodeCount = 0; // reset to start adding actual nodes

        // Add vertices for the main graph
        flow.addVertices(totalVertices * n);

        for (int j = 0; j < k; j++) {
            int a = Integer.parseInt(br.readLine());
            a--;
            flow.addEdge(source, a, 1, 0);
        }

        for (int z = 1; z <= m; z++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int i = 0; i + 1 < totalVertices; i++) {
                int u1 = u + i * n;
                int v1 = v + (i + 1) * n;
                int u2 = u + (i + 1) * n;
                int v2 = v + i * n;
                for (int j = 0; j < k; j++) {
                    flow.addEdge(u1, v1, 1, c + d * (2 * j + 1));
                    flow.addEdge(v2, u2, 1, c + d * (2 * j + 1));
                }
            }
        }

        for (int i = 0; i + 1 < totalVertices; i++) {
            for (int j = 0; j < n; j++) {
                int u = j + i * n;
                int v = j + (i + 1) * n;
                flow.addEdge(u, v, INF, c);
            }
        }

        for (int i = 0; i < totalVertices; i++) {
            flow.addEdge(i * n, sink, INF, 0);
        }

        int[] result = flow.minCostMaxFlow(source, sink, INF);
        System.out.println(result[1]);
    }
}

